window.products.push({"id":1044159,"name":"Bluestar Castle Stainless Steel Egg Slicer","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71uXdxpZbQL._AC_SL1500_.jpg","description":"Made from stainless steel, this easy-to-use egg slicer from Bluestar Castle will provide you with years of culinary convenience, for professionals and beginners alike. Utilizing a folding design and dimensions of 5.5\" L x 3.25\" W x 1\" H, this item stores easily in cabinets or drawers. With no sharpened edges, the stainless steel cables used for slicing will provide both beautiful results for served dishes, as well as a product that is safe for all ages. A must for every kitchen!","images":["https://m.media-amazon.com/images/I/71uXdxpZbQL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Bluestar Castle","source_asin":"B00PNM2PG2","category_path":"Home & Kitchen"},"sku":"BM-1044159","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00PNM2PG2","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00PNM2PG2","price_pending":true,"merchant_ready":false});
